using System.Collections.Generic;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RepairAction", menuName = "Data/Battle/Battle Actions/Hevelius/Repair Action")]
public class RepairAction : BattleAction
{
	[Header("Achievement")]
	[SerializeField]
	private AchievementData astralTinkererAchievementData;

	private CurrentCompanions currentCompanions => ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (currentCompanions.ActiveCompanions.Count >= 2 || currentCompanions.RuntimeCompanions.Count != 2)
		{
			if (currentCompanions.ActiveCompanions.Count < 1)
			{
				return currentCompanions.RuntimeCompanions.Count == 1;
			}
			return false;
		}
		return true;
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.NoInteractionState);
		InitializeCompanion(target, initializeCompanionEntirely: true);
		GameObject aliveCompanion = GetAliveCompanion(target);
		List<GameObject> list = new List<GameObject>();
		list.Add(aliveCompanion);
		List<bool> list2 = new List<bool>();
		list2.Add(aliveCompanion.GetComponent<CompanionEffects>().WasBoosted);
		SpawnCompanionDice(list, recycle: false, source, list2);
		SpawnVFX(GetVFXOwnerPosition(target), 5f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
	}

	public override void AreaCastTarget(List<GameObject> targets, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.NoInteractionState);
		List<GameObject> list = new List<GameObject>();
		List<bool> list2 = new List<bool>();
		for (int i = 0; i < targets.Count; i++)
		{
			InitializeCompanion(targets[i], initializeCompanionEntirely: true);
			SpawnVFX(GetVFXOwnerPosition(targets[i]), 5f);
			GameObject aliveCompanion = GetAliveCompanion(targets[i]);
			list.Add(aliveCompanion);
			list2.Add(aliveCompanion.GetComponent<CompanionEffects>().WasBoosted);
		}
		SpawnCompanionDice(list, recycle: false, source, list2);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
	}

	public void InitializeCompanion(GameObject target, bool initializeCompanionEntirely, int oldCompanionIndex = -1, bool startOfTurnRepair = false)
	{
		if (!startOfTurnRepair)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RepairedSentinelAmount++;
			if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RearmedAndRepairedSentinelAmount >= astralTinkererAchievementData.AchievementVariableAmount)
			{
				astralTinkererAchievementData.Unlock();
			}
		}
		target.transform.parent.gameObject.SetActive(value: false);
		CompanionInitializer component = GetAliveCompanion(target).GetComponent<CompanionInitializer>();
		component.gameObject.SetActive(value: true);
		if (currentCompanions.ActiveCompanions.Count > 0)
		{
			int index = ((oldCompanionIndex == -1) ? currentCompanions.GetCompanionIndex(component.RuntimeCompanion) : oldCompanionIndex);
			currentCompanions.ActiveCompanions.Insert(index, component.gameObject);
		}
		else
		{
			currentCompanions.ActiveCompanions.Add(component.gameObject);
		}
		currentCompanions.DecayedCompanions.Remove(component.gameObject);
		if (initializeCompanionEntirely)
		{
			component.InitializeCompanionEntirelyRepairAction(startOfTurnRepair);
		}
	}

	protected void SpawnCompanionDice(List<GameObject> targets, bool recycle, GameObject source, List<bool> boostedList)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 3, delegate
		{
			List<DiceInstance> list = new List<DiceInstance>();
			for (int i = 0; i < targets.Count; i++)
			{
				CompanionAbility component = targets[i].GetComponent<CompanionAbility>();
				if (boostedList[i])
				{
					component.TurnOnBoosted();
				}
				component.Spawn3DDice();
				list.AddRange(component.GetDiceInstancesToRoll());
			}
			EnableDiceInstances(list, recycle);
			ReferenceSingleton<AssetsReference>.Instance.RerollAction.ExternalCast(list, RollDiceActionType.REPAIR, source);
		});
	}

	private void EnableDiceInstances(List<DiceInstance> diceInstances, bool recycle)
	{
		for (int i = 0; i < diceInstances.Count; i++)
		{
			if (recycle)
			{
				diceInstances[i].DiceMovement.StopAllCoroutines();
				diceInstances[i].Discarding = false;
				diceInstances[i].KillTrail();
			}
			diceInstances[i].ToggleActionEnabled(value: true);
			diceInstances[i].ToggleCompanionDice(value: true);
		}
	}

	public void RecycleActionSpawnCompanionDice(GameObject target, GameObject source)
	{
		List<GameObject> list = new List<GameObject>();
		list.Add(target);
		List<bool> list2 = new List<bool>();
		list2.Add(target.GetComponent<CompanionEffects>().WasBoosted);
		SpawnCompanionDice(list, recycle: true, source, list2);
	}

	protected GameObject GetAliveCompanion(GameObject target)
	{
		return target.transform.parent.parent.GetFirstChild().gameObject;
	}
}
